//! Niche-optimized index newtypes and typed vectors.
//!
//! Refer to AST and IR nodes through `u32` newtypes stored in `IndexVec`s instead of
//! pointers or hash maps: an index is 4 bytes instead of 8, lookups are a bounds check plus an
//! offset, and the type system stops an `ItemId` from indexing the function table.
//!
//! Indices generated by [`newtype_index!`](crate::newtype_index) store the bitwise complement of
//! the value in a [`NonZeroU32`](core::num::NonZeroU32), so `u32::MAX` is never a valid index and
//! `Option<Id>` is still 4 bytes:
//!
//! ```
//! vulcan::newtype_index! {
//!     /// Identifies a function.
//!     pub struct FnId;
//! }
//!
//! assert_eq!(size_of::<Option<FnId>>(), 4);
//!
//! let mut fns = vulcan::index::IndexVec::<FnId, &str>::new();
//! let main = fns.push("main");
//! assert_eq!(fns[main], "main");
//! ```

use std::{
    fmt,
    marker::PhantomData,
    ops::{Index, IndexMut},
    slice,
};

/// A typed index into an [`IndexVec`].
pub trait Idx: Copy + Eq + Ord + fmt::Debug + 'static {
    /// Creates an index from a `usize`.
    ///
    /// # Panics
    ///
    /// Panics if `index` is out of range for the index type.
    fn from_usize(index: usize) -> Self;

    /// Returns the index as a `usize`.
    fn index(self) -> usize;
}

/// Defines `u32` index newtypes with a niche, so `Option<Self>` is 4 bytes.
///
/// The type implements [`Idx`], [`CacheKey`](crate::cache::CacheKey) (with a dense cache),
/// `Copy`, `Eq`, `Ord`, `Hash` and `Debug`, and exposes
/// `from_u32`, `try_from_u32`, `as_u32`, `as_usize` and `MAX`.
#[macro_export]
macro_rules! newtype_index {
    ($($(#[$attr:meta])* $vis:vis struct $name:ident;)*) => {$(
        $(#[$attr])*
        #[derive(Clone, Copy, PartialEq, Eq, Hash)]
        $vis struct $name(::core::num::NonZeroU32);

        impl $name {
            /// The largest representable index.
            $vis const MAX_INDEX: u32 = u32::MAX - 1;

            /// The largest index value. `!MAX_INDEX == 1`, the smallest non-zero value.
            $vis const MAX: Self = Self(::core::num::NonZeroU32::MIN);

            /// Creates an index, or returns `None` if `value` is `u32::MAX`.
            #[inline]
            #[must_use]
            $vis const fn try_from_u32(value: u32) -> ::core::option::Option<Self> {
                match ::core::num::NonZeroU32::new(!value) {
                    ::core::option::Option::Some(repr) => ::core::option::Option::Some(Self(repr)),
                    ::core::option::Option::None => ::core::option::Option::None,
                }
            }

            /// Creates an index.
            ///
            /// # Panics
            ///
            /// Panics if `value` is `u32::MAX`.
            #[inline]
            #[must_use]
            #[track_caller]
            $vis const fn from_u32(value: u32) -> Self {
                assert!(value <= Self::MAX_INDEX, "index out of range");
                match Self::try_from_u32(value) {
                    ::core::option::Option::Some(index) => index,
                    ::core::option::Option::None => Self::MAX,
                }
            }

            /// Returns the index as a `u32`.
            #[inline]
            #[must_use]
            $vis const fn as_u32(self) -> u32 {
                !self.0.get()
            }

            /// Returns the index as a `usize`.
            #[inline]
            #[must_use]
            $vis const fn as_usize(self) -> usize {
                self.as_u32() as usize
            }
        }

        // The stored value is complemented, so ordering must go through the decoded index.
        impl ::core::cmp::PartialOrd for $name {
            #[inline]
            fn partial_cmp(&self, other: &Self) -> ::core::option::Option<::core::cmp::Ordering> {
                ::core::option::Option::Some(::core::cmp::Ord::cmp(self, other))
            }
        }

        impl ::core::cmp::Ord for $name {
            #[inline]
            fn cmp(&self, other: &Self) -> ::core::cmp::Ordering {
                self.as_u32().cmp(&other.as_u32())
            }
        }

        impl ::core::fmt::Debug for $name {
            fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
                write!(f, "{}({})", stringify!($name), self.as_u32())
            }
        }

        impl $crate::cache::CacheKey for $name {
            type Cache<V: Copy> = $crate::cache::DenseCache<Self, V>;
        }

        impl $crate::index::Idx for $name {
            #[inline]
            #[track_caller]
            fn from_usize(index: usize) -> Self {
                match u32::try_from(index) {
                    ::core::result::Result::Ok(value) => Self::from_u32(value),
                    ::core::result::Result::Err(_) => Self::from_u32(u32::MAX),
                }
            }

            #[inline]
            fn index(self) -> usize {
                self.as_usize()
            }
        }
    )*};
}

/// Ties a container to its index type without owning an `I`, so the container stays `Send`,
/// `Sync` and covariant whatever `I` is.
type IndexMarker<I> = PhantomData<fn() -> I>;

/// A `Vec<T>` indexed by `I` instead of `usize`.
pub struct IndexVec<I, T> {
    raw: Vec<T>,
    _index: IndexMarker<I>,
}

impl<I: Idx, T> IndexVec<I, T> {
    /// Creates an empty vector.
    #[inline]
    #[must_use]
    pub const fn new() -> Self {
        Self { raw: Vec::new(), _index: PhantomData }
    }

    /// Creates an empty vector with room for `capacity` elements.
    #[inline]
    #[must_use]
    pub fn with_capacity(capacity: usize) -> Self {
        Self { raw: Vec::with_capacity(capacity), _index: PhantomData }
    }

    /// Wraps an existing vector.
    #[inline]
    #[must_use]
    pub const fn from_raw(raw: Vec<T>) -> Self {
        Self { raw, _index: PhantomData }
    }

    /// Returns the underlying vector.
    #[inline]
    #[must_use]
    pub fn into_raw(self) -> Vec<T> {
        self.raw
    }

    /// Returns the elements as a plain slice.
    #[inline]
    #[must_use]
    pub fn as_raw_slice(&self) -> &[T] {
        &self.raw
    }

    /// Appends `value` and returns its index.
    #[inline]
    #[track_caller]
    pub fn push(&mut self, value: T) -> I {
        let index = self.next_index();
        self.raw.push(value);
        index
    }

    /// Returns the index the next [`push`](Self::push) will return.
    #[inline]
    #[must_use]
    #[track_caller]
    pub fn next_index(&self) -> I {
        I::from_usize(self.raw.len())
    }

    /// Returns the number of elements.
    #[inline]
    #[must_use]
    pub const fn len(&self) -> usize {
        self.raw.len()
    }

    /// Returns `true` if the vector has no elements.
    #[inline]
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.raw.is_empty()
    }

    /// Returns the element at `index`, if any.
    #[inline]
    #[must_use]
    pub fn get(&self, index: I) -> Option<&T> {
        self.raw.get(index.index())
    }

    /// Returns the element at `index` mutably, if any.
    #[inline]
    #[must_use]
    pub fn get_mut(&mut self, index: I) -> Option<&mut T> {
        self.raw.get_mut(index.index())
    }

    /// Iterates over the elements.
    #[inline]
    pub fn iter(&self) -> slice::Iter<'_, T> {
        self.raw.iter()
    }

    /// Iterates over the elements mutably.
    #[inline]
    pub fn iter_mut(&mut self) -> slice::IterMut<'_, T> {
        self.raw.iter_mut()
    }

    /// Iterates over `(index, element)` pairs.
    #[inline]
    #[must_use = "iterators are lazy and do nothing unless consumed"]
    pub fn iter_enumerated(&self) -> impl ExactSizeIterator<Item = (I, &T)> {
        self.raw.iter().enumerate().map(|(i, value)| (I::from_usize(i), value))
    }

    /// Iterates over all valid indices.
    #[inline]
    #[must_use = "iterators are lazy and do nothing unless consumed"]
    pub fn indices(&self) -> impl ExactSizeIterator<Item = I> + use<I, T> {
        (0..self.raw.len()).map(I::from_usize)
    }
}

impl<I: Idx, T> Default for IndexVec<I, T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<I: Idx, T: Clone> Clone for IndexVec<I, T> {
    fn clone(&self) -> Self {
        Self::from_raw(self.raw.clone())
    }
}

impl<I: Idx, T: PartialEq> PartialEq for IndexVec<I, T> {
    fn eq(&self, other: &Self) -> bool {
        self.raw == other.raw
    }
}

impl<I: Idx, T: Eq> Eq for IndexVec<I, T> {}

impl<I: Idx, T: fmt::Debug> fmt::Debug for IndexVec<I, T> {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_map().entries(self.iter_enumerated()).finish()
    }
}

impl<I: Idx, T> Index<I> for IndexVec<I, T> {
    type Output = T;

    #[inline]
    #[track_caller]
    fn index(&self, index: I) -> &T {
        &self.raw[index.index()]
    }
}

impl<I: Idx, T> IndexMut<I> for IndexVec<I, T> {
    #[inline]
    #[track_caller]
    fn index_mut(&mut self, index: I) -> &mut T {
        &mut self.raw[index.index()]
    }
}

impl<I: Idx, T> FromIterator<T> for IndexVec<I, T> {
    fn from_iter<It: IntoIterator<Item = T>>(iter: It) -> Self {
        Self::from_raw(iter.into_iter().collect())
    }
}

impl<'a, I: Idx, T> IntoIterator for &'a IndexVec<I, T> {
    type Item = &'a T;
    type IntoIter = slice::Iter<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.raw.iter()
    }
}

impl<'a, I: Idx, T> IntoIterator for &'a mut IndexVec<I, T> {
    type Item = &'a mut T;
    type IntoIter = slice::IterMut<'a, T>;

    fn into_iter(self) -> Self::IntoIter {
        self.raw.iter_mut()
    }
}

impl<I: Idx, T> IntoIterator for IndexVec<I, T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;

    fn into_iter(self) -> Self::IntoIter {
        self.raw.into_iter()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    crate::newtype_index! {
        /// Test index.
        struct NodeId;
        /// Second test index, to check the macro accepts several types.
        struct EdgeId;
    }

    #[test]
    fn option_uses_the_niche() {
        assert_eq!(size_of::<NodeId>(), 4);
        assert_eq!(size_of::<Option<NodeId>>(), 4);
        assert_eq!(size_of::<Option<EdgeId>>(), 4);
    }

    #[test]
    fn round_trips_and_orders_by_value() {
        for value in [0, 1, 42, NodeId::MAX_INDEX] {
            assert_eq!(NodeId::from_u32(value).as_u32(), value);
        }
        assert!(NodeId::try_from_u32(u32::MAX).is_none());
        assert_eq!(NodeId::MAX.as_u32(), NodeId::MAX_INDEX);
        assert!(NodeId::from_u32(1) < NodeId::from_u32(2));
        assert!(NodeId::from_u32(0) < NodeId::MAX);
        assert_eq!(format!("{:?}", NodeId::from_u32(7)), "NodeId(7)");
    }

    #[test]
    #[should_panic(expected = "index out of range")]
    fn rejects_max() {
        assert_eq!(NodeId::from_u32(u32::MAX).as_u32(), 0);
    }

    #[test]
    fn index_vec_basics() {
        let mut v = IndexVec::<NodeId, char>::new();
        let a = v.push('a');
        let b = v.push('b');
        assert_eq!((a.as_u32(), b.as_u32()), (0, 1));
        v[b] = 'c';
        assert_eq!(v.get(b), Some(&'c'));
        assert_eq!(
            v.iter_enumerated().map(|(i, c)| (i.as_u32(), *c)).collect::<Vec<_>>(),
            [(0, 'a'), (1, 'c')]
        );
        assert_eq!(v.indices().collect::<Vec<_>>(), [a, b]);
        assert_eq!(v.next_index().as_u32(), 2);
    }
}
